{
  "name": "Math Word Problem Generator",
  "description": "An application for classroom teachers to generate curriculum-aligned, differentiated math word problems with support features and teacher-facing content."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

import React, { useState, useCallback } from 'react';
import { AppHeader } from './components/Header';
import { SettingsForm } from './components/SettingsForm';
import { OutputDisplay } from './components/OutputDisplay';
import { Spinner } from './components/Spinner';
import type { FormState, GeneratedProblem } from './types';
import { generateWordProblems } from './services/geminiService';
import { DEFAULT_FORM_STATE } from './constants';
import { DownloadIcon, GoogleDocsIcon, StudentSheetIcon, TeacherKeyIcon } from './components/icons';

export default function App() {
  const [formState, setFormState] = useState<FormState>(DEFAULT_FORM_STATE);
  const [generatedContent, setGeneratedContent] = useState<GeneratedProblem | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const handleGenerate = useCallback(async () => {
    setIsLoading(true);
    setError(null);
    setGeneratedContent(null);
    try {
      const content = await generateWordProblems(formState);
      setGeneratedContent(content);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred.');
      console.error(err);
    } finally {
      setIsLoading(false);
    }
  }, [formState]);

  const handlePrint = (isTeacherView: boolean) => {
    const printContent = document.getElementById(isTeacherView ? 'teacher-key' : 'student-worksheet');
    if (printContent) {
      const originalContents = document.body.innerHTML;
      const title = `Math Word Problems - ${formState.mathConcept}`;
      const printableArea = `
        <html>
        <head>
          <title>${title}</title>
          <script src="https://cdn.tailwindcss.com"></script>
          <style>
            @media print {
              body { -webkit-print-color-adjust: exact; }
              .no-print { display: none; }
            }
            .prose h3 { margin-top: 1em; }
          </style>
        </head>
        <body class="p-8 font-sans">
          <h1 class="text-3xl font-bold mb-4">${title}</h1>
          <h2 class="text-xl text-gray-600 mb-6">Grade ${formState.gradeLevel} &ndash; ${isTeacherView ? 'Teacher Answer Key' : 'Student Worksheet'}</h2>
          ${printContent.innerHTML}
        </body>
        </html>
      `;
      document.body.innerHTML = printableArea;
      window.print();
      document.body.innerHTML = originalContents;
      // We need to re-initialize the app state after printing replaces the DOM
      window.location.reload(); 
    }
  };


  return (
    <div className="bg-slate-50 min-h-screen font-sans text-slate-800">
      <div className="container mx-auto px-4 py-8 max-w-4xl">
        <AppHeader />
        <main className="mt-8 space-y-6">
          <SettingsForm formState={formState} setFormState={setFormState} />
          <div className="text-center">
            <button
              onClick={handleGenerate}
              disabled={isLoading}
              className="bg-green-600 hover:bg-green-700 disabled:bg-green-400 text-white font-bold py-4 px-12 rounded-lg text-xl shadow-lg transition-transform transform hover:scale-105 disabled:scale-100 disabled:cursor-wait"
            >
              {isLoading ? 'Generating...' : 'Generate Word Problems'}
            </button>
          </div>

          {isLoading && <Spinner />}

          {error && (
            <div className="bg-red-100 border-l-4 border-red-500 text-red-700 p-4 rounded-md" role="alert">
              <p className="font-bold">Error</p>
              <p>{error}</p>
            </div>
          )}

          {generatedContent && !isLoading && (
            <div className="bg-white p-6 rounded-lg shadow-md mt-6">
              <OutputDisplay content={generatedContent} />
              <div className="mt-8 border-t pt-6 space-y-3">
                 <button onClick={() => handlePrint(false)} className="flex items-center space-x-3 text-slate-600 hover:text-blue-600 w-full text-left p-2 rounded-md transition-colors">
                    <StudentSheetIcon />
                    <span>Student Worksheet</span>
                </button>
                <button onClick={() => handlePrint(true)} className="flex items-center space-x-3 text-slate-600 hover:text-blue-600 w-full text-left p-2 rounded-md transition-colors">
                    <TeacherKeyIcon />
                    <span>Teacher Answer Key</span>
                </button>
                <button className="flex items-center space-x-3 text-slate-400 cursor-not-allowed w-full text-left p-2 rounded-md" disabled>
                    <GoogleDocsIcon />
                    <span>Export to Google Docs (coming soon)</span>
                </button>
                <button onClick={() => handlePrint(false)} className="flex items-center space-x-3 text-slate-600 hover:text-blue-600 w-full text-left p-2 rounded-md transition-colors">
                    <DownloadIcon />
                    <span>Download PDF</span>
                </button>
              </div>
            </div>
          )}
        </main>
      </div>
    </div>
  );
}

export interface FormState {
  mathConcept: string;
  gradeLevel: string;
  mathStrand: string;
  curriculum: string;
  context: string;
  differentiation: {
    scaffolded: boolean;
    onLevel: boolean;
    challenge: boolean;
  };
  supports: {
    visualModels: boolean;
    keyVocabulary: boolean;
    stepByStepHints: boolean;
    multipleStrategies: boolean;
  };
}

interface ProblemDetail {
  problemText: string;
  workspacePrompt: string;
}

interface TeacherKeyDetail {
  completeSolution: string;
  multipleStrategies: string[];
  commonMisconceptions: string[];
  successCriteria: string[];
}

export interface GeneratedProblem {
  studentWorksheet: {
    scaffolded?: ProblemDetail;
    onLevel?: ProblemDetail;
    challenge?: ProblemDetail;
  };
  teacherKey: {
    scaffolded?: TeacherKeyDetail;
    onLevel?: TeacherKeyDetail;
    challenge?: TeacherKeyDetail;
  };
}

