import React from 'react';
import type { FormState } from '../types';
import { GRADE_LEVELS, MATH_STRANDS, CURRICULA, CONTEXTS } from '../constants';
import { ToggleSwitch } from './ToggleSwitch';
import { ChallengeIcon, OnLevelIcon, ScaffoldIcon } from './icons';

interface SettingsFormProps {
  formState: FormState;
  setFormState: React.Dispatch<React.SetStateAction<FormState>>;
}

export const SettingsForm: React.FC<SettingsFormProps> = ({ formState, setFormState }) => {
  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setFormState(prev => ({ ...prev, [name]: value }));
  };

  const handleContextChange = (context: string) => {
    setFormState(prev => ({ ...prev, context }));
  };

  const handleDifferentiationToggle = (level: keyof FormState['differentiation']) => {
    setFormState(prev => ({
      ...prev,
      differentiation: { ...prev.differentiation, [level]: !prev.differentiation[level] }
    }));
  };

  const handleSupportChange = (support: keyof FormState['supports']) => {
    setFormState(prev => ({
      ...prev,
      supports: { ...prev.supports, [support]: !prev.supports[support] }
    }));
  };

  const FormSection: React.FC<{ title: string; children: React.ReactNode }> = ({ title, children }) => (
    <div className="bg-white p-6 rounded-lg shadow-md">
      <h2 className="text-xl font-semibold text-blue-700 mb-4 pb-2 border-b">{title}</h2>
      {children}
    </div>
  );

  return (
    <div className="space-y-6">
      <FormSection title="Choose Your Problem Settings">
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          <div>
            <label htmlFor="mathConcept" className="block text-sm font-medium text-slate-700 mb-1">Math Concept</label>
            <input type="text" id="mathConcept" name="mathConcept" value={formState.mathConcept} onChange={handleInputChange} className="w-full border-slate-300 rounded-md shadow-sm focus:ring-blue-500 focus:border-blue-500" />
          </div>
          <div>
            <label htmlFor="gradeLevel" className="block text-sm font-medium text-slate-700 mb-1">Grade Level</label>
            <select id="gradeLevel" name="gradeLevel" value={formState.gradeLevel} onChange={handleInputChange} className="w-full border-slate-300 rounded-md shadow-sm focus:ring-blue-500 focus:border-blue-500">
              {GRADE_LEVELS.map(g => <option key={g} value={g}>Grade {g}</option>)}
            </select>
          </div>
          <div>
            <label htmlFor="mathStrand" className="block text-sm font-medium text-slate-700 mb-1">Topic / Strand</label>
            <select id="mathStrand" name="mathStrand" value={formState.mathStrand} onChange={handleInputChange} className="w-full border-slate-300 rounded-md shadow-sm focus:ring-blue-500 focus:border-blue-500">
              {MATH_STRANDS.map(s => <option key={s} value={s}>{s}</option>)}
            </select>
          </div>
          <div>
            <label htmlFor="curriculum" className="block text-sm font-medium text-slate-700 mb-1">Canadian Curriculum</label>
            <select id="curriculum" name="curriculum" value={formState.curriculum} onChange={handleInputChange} className="w-full border-slate-300 rounded-md shadow-sm focus:ring-blue-500 focus:border-blue-500">
              {CURRICULA.map(c => <option key={c} value={c}>{c}</option>)}
            </select>
          </div>
          <div className="md:col-span-2">
             <label className="block text-sm font-medium text-slate-700 mb-2">Context / Theme</label>
             <div className="flex flex-wrap gap-2">
                {CONTEXTS.map(c => (
                    <button key={c.id} onClick={() => handleContextChange(c.id)}
                        className={`px-4 py-2 rounded-full text-sm font-semibold border-2 transition-colors flex items-center gap-2 ${formState.context === c.id ? 'bg-blue-600 text-white border-blue-600' : 'bg-white text-slate-700 border-slate-300 hover:bg-slate-100'}`}>
                        <span>{formState.context === c.id ? '✓' : c.icon}</span>
                        {c.name}
                    </button>
                ))}
             </div>
          </div>
        </div>
      </FormSection>

      <FormSection title="Select Differentiation Levels">
        <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            <ToggleSwitch label="Scaffolded Support" icon={<ScaffoldIcon />} enabled={formState.differentiation.scaffolded} onToggle={() => handleDifferentiationToggle('scaffolded')} />
            <ToggleSwitch label="On-Level" icon={<OnLevelIcon />} enabled={formState.differentiation.onLevel} onToggle={() => handleDifferentiationToggle('onLevel')} />
            <ToggleSwitch label="Challenge Mode" icon={<ChallengeIcon />} enabled={formState.differentiation.challenge} onToggle={() => handleDifferentiationToggle('challenge')} />
        </div>
      </FormSection>

      <FormSection title="Additional Supports">
        <div className="grid grid-cols-1 sm:grid-cols-2 gap-x-8 gap-y-4">
            {Object.keys(formState.supports).map((supportKey) => {
                const key = supportKey as keyof FormState['supports'];
                const label = key.replace(/([A-Z])/g, ' $1').replace(/^./, (str) => str.toUpperCase());
                return (
                    <label key={key} className="flex items-center space-x-3 cursor-pointer">
                        <input type="checkbox" checked={formState.supports[key]} onChange={() => handleSupportChange(key)} className="h-5 w-5 rounded border-gray-300 text-blue-600 focus:ring-blue-500" />
                        <span className="text-slate-700">{label}</span>
                    </label>
                );
            })}
        </div>
      </FormSection>
    </div>
  );
};

import React, { useState } from 'react';
import type { GeneratedProblem } from '../types';

interface OutputDisplayProps {
  content: GeneratedProblem;
}

export const OutputDisplay: React.FC<OutputDisplayProps> = ({ content }) => {
  const [view, setView] = useState<'student' | 'teacher'>('student');

  const renderProblem = (level: 'scaffolded' | 'onLevel' | 'challenge', title: string) => {
    const problem = content.studentWorksheet[level];
    if (!problem) return null;

    return (
      <div key={level}>
        <h3 className="text-xl font-bold text-blue-700 mb-2">{title}</h3>
        <p className="mb-4 whitespace-pre-wrap">{problem.problemText}</p>
        <div className="border-t border-dashed pt-4">
          <p className="italic text-slate-600">{problem.workspacePrompt}</p>
          <div className="mt-4 h-32 border rounded-md bg-slate-50"></div>
        </div>
      </div>
    );
  };

  const renderTeacherKey = (level: 'scaffolded' | 'onLevel' | 'challenge', title: string) => {
    const key = content.teacherKey[level];
    if (!key) return null;

    return (
      <div key={level} className="mb-8">
        <h3 className="text-xl font-bold text-blue-700 mb-3 pb-2 border-b">{title}</h3>
        <div className="space-y-4">
          <div>
            <h4 className="font-semibold text-slate-800">Complete Solution:</h4>
            <p className="text-slate-700 whitespace-pre-wrap">{key.completeSolution}</p>
          </div>
          <div>
            <h4 className="font-semibold text-slate-800">Multiple Strategies:</h4>
            <ul className="list-disc list-inside text-slate-700 space-y-1">
              {key.multipleStrategies.map((s, i) => <li key={i}>{s}</li>)}
            </ul>
          </div>
          <div>
            <h4 className="font-semibold text-slate-800">Common Misconceptions:</h4>
            <ul className="list-disc list-inside text-slate-700 space-y-1">
              {key.commonMisconceptions.map((m, i) => <li key={i}>{m}</li>)}
            </ul>
          </div>
          <div>
            <h4 className="font-semibold text-slate-800">Success Criteria:</h4>
            <ul className="list-disc list-inside text-slate-700 space-y-1">
              {key.successCriteria.map((c, i) => <li key={i}>{c}</li>)}
            </ul>
          </div>
        </div>
      </div>
    );
  };

  return (
    <div className="prose max-w-none">
      <div className="flex justify-center mb-6 no-print">
        <div className="bg-slate-100 p-1 rounded-lg flex space-x-1">
          <button onClick={() => setView('student')} className={`px-4 py-2 rounded-md font-semibold ${view === 'student' ? 'bg-white shadow' : 'text-slate-600 hover:bg-slate-200'}`}>Student Worksheet</button>
          <button onClick={() => setView('teacher')} className={`px-4 py-2 rounded-md font-semibold ${view === 'teacher' ? 'bg-white shadow' : 'text-slate-600 hover:bg-slate-200'}`}>Teacher Key</button>
        </div>
      </div>

      {view === 'student' && (
        <div id="student-worksheet" className="space-y-8">
          {renderProblem('scaffolded', 'Scaffolded / Supported Problem')}
          {content.studentWorksheet.scaffolded && (content.studentWorksheet.onLevel || content.studentWorksheet.challenge) && <hr className="my-8"/>}
          {renderProblem('onLevel', 'Core / On-Level Problem')}
          {content.studentWorksheet.onLevel && content.studentWorksheet.challenge && <hr className="my-8"/>}
          {renderProblem('challenge', 'Extension / Enrichment Problem')}
        </div>
      )}

      {view === 'teacher' && (
        <div id="teacher-key">
          {renderTeacherKey('scaffolded', 'Scaffolded / Supported Problem Key')}
          {renderTeacherKey('onLevel', 'Core / On-Level Problem Key')}
          {renderTeacherKey('challenge', 'Extension / Enrichment Problem Key')}
        </div>
      )}
    </div>
  );
};

