import React from 'react';

interface ToggleSwitchProps {
  label: string;
  icon: React.ReactNode;
  enabled: boolean;
  onToggle: () => void;
}

export const ToggleSwitch: React.FC<ToggleSwitchProps> = ({ label, icon, enabled, onToggle }) => {
  return (
    <div
      onClick={onToggle}
      className={`p-3 border-2 rounded-lg flex items-center justify-between cursor-pointer transition-all ${
        enabled ? 'border-green-500 bg-green-50' : 'border-slate-300 bg-white hover:bg-slate-50'
      }`}
    >
      <div className="flex items-center space-x-3">
        <span className={enabled ? 'text-green-600' : 'text-slate-500'}>{icon}</span>
        <span className={`font-semibold ${enabled ? 'text-green-800' : 'text-slate-700'}`}>{label}</span>
      </div>
      <div className={`relative w-12 h-6 rounded-full flex items-center transition-colors ${enabled ? 'bg-green-500' : 'bg-slate-300'}`}>
        <span
          className={`absolute left-0 inline-block w-5 h-5 bg-white rounded-full shadow transform transition-transform ${
            enabled ? 'translate-x-6' : 'translate-x-1'
          }`}
        />
        <span className="absolute right-1 text-xs font-bold text-white">{enabled ? 'ON' : ''}</span>
      </div>
    </div>
  );
};

import React from 'react';

export const Spinner: React.FC = () => {
    return (
