import { GoogleGenAI, Type } from "@google/genai";
import type { FormState, GeneratedProblem } from '../types';

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export async function generateWordProblems(settings: FormState): Promise<GeneratedProblem> {
  const selectedLevels = Object.entries(settings.differentiation)
    .filter(([, value]) => value)
    .map(([key]) => key);

  if (selectedLevels.length === 0) {
    throw new Error("Please select at least one differentiation level.");
  }

  const selectedSupports = Object.entries(settings.supports)
    .filter(([, value]) => value)
    .map(([key]) => key.replace(/([A-Z])/g, ' $1').toLowerCase());

  const prompt = `
    You are an expert curriculum designer and math teacher specializing in creating differentiated, inclusive, and curriculum-aligned math word problems for K-12 students in Canada. Your responses must be structured, clear, and ready for classroom use.

    Generate a set of math word problems based on the following criteria:
    - Math Concept: ${settings.mathConcept}
    - Grade Level: ${settings.gradeLevel}
    - Curriculum: ${settings.curriculum}
    - Context/Theme: ${settings.context}
    - Differentiation Levels to generate: ${selectedLevels.join(', ')}
    - Additional Supports to include: ${selectedSupports.join(', ') || 'None'}

    For each differentiation level, provide:
    1.  A student-friendly word problem.
    2.  A prompt for students to show their mathematical thinking (e.g., "Show your work in the space below.").
    3.  A complete solution for the teacher.
    4.  Suggestions for multiple strategies to solve the problem.
    5.  A list of common misconceptions students might have.
    6.  A list of success criteria for assessment.

    Ensure the language is inclusive, classroom-appropriate, and aligned with Universal Design for Learning (UDL) principles.
    The response MUST follow the provided JSON schema.
  `;

  const responseSchema = {
      type: Type.OBJECT,
      properties: {
        studentWorksheet: {
          type: Type.OBJECT,
          properties: {
            scaffolded: {
              type: Type.OBJECT,
              properties: {
                problemText: { type: Type.STRING },
                workspacePrompt: { type: Type.STRING },
              },
            },
            onLevel: {
              type: Type.OBJECT,
              properties: {
                problemText: { type: Type.STRING },
                workspacePrompt: { type: Type.STRING },
              },
            },
            challenge: {
              type: Type.OBJECT,
              properties: {
                problemText: { type: Type.STRING },
                workspacePrompt: { type: Type.STRING },
              },
            },
          },
        },
        teacherKey: {
          type: Type.OBJECT,
          properties: {
            scaffolded: {
              type: Type.OBJECT,
              properties: {
                completeSolution: { type: Type.STRING },
                multipleStrategies: { type: Type.ARRAY, items: { type: Type.STRING } },
                commonMisconceptions: { type: Type.ARRAY, items: { type: Type.STRING } },
                successCriteria: { type: Type.ARRAY, items: { type: Type.STRING } },
              },
            },
            onLevel: {
              type: Type.OBJECT,
              properties: {
                completeSolution: { type: Type.STRING },
                multipleStrategies: { type: Type.ARRAY, items: { type: Type.STRING } },
                commonMisconceptions: { type: Type.ARRAY, items: { type: Type.STRING } },
                successCriteria: { type: Type.ARRAY, items: { type: Type.STRING } },
              },
            },
            challenge: {
              type: Type.OBJECT,
              properties: {
                completeSolution: { type: Type.STRING },
                multipleStrategies: { type: Type.ARRAY, items: { type: Type.STRING } },
                commonMisconceptions: { type: Type.ARRAY, items: { type: Type.STRING } },
                successCriteria: { type: Type.ARRAY, items: { type: Type.STRING } },
              },
            },
          },
        },
      },
  };

  try {
    const response = await ai.models.generateContent({
        model: 'gemini-3-pro-preview',
        contents: prompt,
        config: {
            responseMimeType: 'application/json',
            responseSchema: responseSchema,
            temperature: 0.8,
        }
    });

    const text = response.text;
    if (!text) {
        throw new Error("Received an empty response from the API.");
    }

    return JSON.parse(text) as GeneratedProblem;

  } catch (error) {
    console.error("Error calling Gemini API:", error);
    throw new Error("Failed to generate word problems. Please check your API key and try again.");
  }
}

