      ...prev,
      differentiation: { ...prev.differentiation, [level]: !prev.differentiation[level] }
    }));
  };

  const handleSupportChange = (support: keyof FormState['supports']) => {
    setFormState(prev => ({
      ...prev,
      supports: { ...prev.supports, [support]: !prev.supports[support] }
    }));
  };

  return (
    <div className="space-y-6">
