import React, { useState, useCallback } from 'react';
import { AppHeader } from './components/Header';
import { SettingsForm } from './components/SettingsForm';
import { OutputDisplay } from './components/OutputDisplay';
import type { FormState, GeneratedProblem } from './types';
import { generateWordProblemsStream } from './services/geminiService';
import { DEFAULT_FORM_STATE } from './constants';
import { GoogleDocsIcon, StudentSheetIcon } from './components/icons';

export default function App() {
  const [formState, setFormState] = useState<FormState>(DEFAULT_FORM_STATE);
  const [generatedContent, setGeneratedContent] = useState<GeneratedProblem | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [activeView, setActiveView] = useState<'student' | 'teacher'>('student');
  const [streamingText, setStreamingText] = useState<string | null>(null);


  const handleGenerate = useCallback(async () => {
    setIsLoading(true);
    setError(null);
    setGeneratedContent(null);
    setStreamingText('');

    try {
      const stream = await generateWordProblemsStream(formState);
      let accumulatedText = '';
      for await (const chunk of stream) {
          const chunkText = chunk.text;
          if (chunkText) {
              accumulatedText += chunkText;
              setStreamingText(accumulatedText);
          }
      }

      const cleanedJson = accumulatedText.replace(/^```json\s*/, '').replace(/```$/, '');
      const content = JSON.parse(cleanedJson);
      setGeneratedContent(content);
      setStreamingText(null);

    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred.');
      setStreamingText(null);
      console.error(err);
    } finally {
      setIsLoading(false);
    }
  }, [formState]);

  const handlePrint = () => {
    window.print();
  };


  return (
    <div className="bg-slate-50 min-h-screen font-sans text-slate-800">
      <AppHeader />
      <div className="container mx-auto px-4 py-8 max-w-4xl">
        <main className="mt-8 space-y-6">
          <SettingsForm formState={formState} setFormState={setFormState} />
          <div className="text-center">
            <button
              onClick={handleGenerate}
              disabled={isLoading}
              className="bg-green-600 hover:bg-green-700 disabled:bg-green-400 text-white font-bold py-4 px-12 rounded-lg text-xl shadow-lg transition-transform transform hover:scale-105 disabled:scale-100 disabled:cursor-wait animate-pulse disabled:animate-none"
            >
              {isLoading ? 'Generating...' : 'Generate Word Problems'}
            </button>
          </div>

          {isLoading && streamingText !== null && (
            <div className="bg-slate-800 text-white font-mono text-sm p-4 rounded-lg shadow-md mt-6 animate-fade-in">
              <h3 className="text-lg font-semibold mb-3 text-slate-300 flex items-center">
                <div className="w-4 h-4 border-2 border-slate-400 border-t-transparent rounded-full animate-spin mr-3"></div>
                Generating Response Stream...
              </h3>
              <pre className="whitespace-pre-wrap break-all text-slate-400"><code>{streamingText}</code></pre>
            </div>
          )}

          {error && (
            <div className="bg-red-100 border-l-4 border-red-500 text-red-700 p-4 rounded-md" role="alert">
              <p className="font-bold">Error</p>
              <p>{error}</p>
            </div>
          )}

          {generatedContent && !isLoading && (
            <div className="bg-white p-6 rounded-lg shadow-md mt-6">
              <div id="printable-area">
                 <OutputDisplay 
                    content={generatedContent} 
                    activeView={activeView}
                    setActiveView={setActiveView}
                    printInfo={{
                      mathConcept: formState.mathConcept,
                      gradeLevel: formState.gradeLevel
                    }}
                 />
              </div>

              <div className="mt-8 border-t pt-6 flex flex-col sm:flex-row sm:justify-around space-y-3 sm:space-y-0 sm:space-x-3 no-print">
                 <button onClick={handlePrint} className="flex items-center justify-center space-x-3 text-slate-600 hover:text-purple-600 hover:bg-purple-50 w-full text-left p-3 rounded-md transition-colors font-semibold">
                    <StudentSheetIcon />
                    <span>Print Worksheet / Key</span>
                </button>
                <button className="flex items-center justify-center space-x-3 text-slate-400 cursor-not-allowed w-full text-left p-3 rounded-md font-semibold" disabled>
                    <GoogleDocsIcon />
                    <span>Export to Google Docs</span>
                </button>
              </div>
            </div>
          )}
        </main>
      </div>
    </div>
  );
}

import { GoogleGenAI, Type } from "@google/genai";
import type { FormState, GeneratedProblem } from '../types';

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export async function generateWordProblemsStream(settings: FormState) {
  const selectedLevels = Object.entries(settings.differentiation)
    .filter(([, value]) => value)
    .map(([key]) => key);

  if (selectedLevels.length === 0) {
    throw new Error("Please select at least one differentiation level.");
  }

  const selectedSupports = Object.entries(settings.supports)
    .filter(([, value]) => value)
    .map(([key]) => key.replace(/([A-Z])/g, ' $1').toLowerCase());

  const prompt = `
    You are an expert curriculum designer and math teacher specializing in creating differentiated, inclusive, and curriculum-aligned math word problems for K-12 students in Canada. Your responses must be structured, clear, and ready for classroom use.

    Generate a set of ${settings.numberOfQuestions} unique math word problems in total, distributed across the following criteria:
    - Math Concept: ${settings.mathConcept}
    - Grade Level: ${settings.gradeLevel}
    - Curriculum: ${settings.curriculum}
    - Context/Theme: ${settings.context}
    - Differentiation Levels to generate for: ${selectedLevels.join(', ')} (distribute the problems amongst these levels)
    - Additional Supports to include: ${selectedSupports.join(', ') || 'None'}

    For each problem, provide the following details in the specified JSON structure:
    - For the 'studentWorksheet':
      1. 'problemText': The core, student-friendly word problem.
      2. 'stepByStepHints': If the 'step by step hints' support was requested, provide an array of strings, with each string being a distinct step to guide the student. These hints MUST NOT be included in the 'problemText'. If hints were not requested, this field can be omitted or be an empty array.
      3. 'workspacePrompt': A generic prompt for students to show their mathematical thinking (e.g., "Show your work in the space below.").
    - For the 'teacherKey':
      1. A complete solution.
      2. Suggestions for multiple strategies.
      3. A list of common misconceptions.
      4. A list of success criteria for assessment.

    Ensure the language is inclusive, classroom-appropriate, and aligned with Universal Design for Learning (UDL) principles.
    The response MUST be a single, valid JSON object following the structure below. Do not wrap the JSON in markdown backticks.

    JSON Structure:
    {
      "studentWorksheet": {
        "scaffolded": [ { "problemText": "...", "stepByStepHints": [], "workspacePrompt": "..." } ],
        "onLevel": [ { "problemText": "...", "stepByStepHints": [], "workspacePrompt": "..." } ],
        "challenge": [ { "problemText": "...", "stepByStepHints": [], "workspacePrompt": "..." } ]
      },
      "teacherKey": {
        "scaffolded": [ { "completeSolution": "...", "multipleStrategies": [], "commonMisconceptions": [], "successCriteria": [] } ],
        "onLevel": [ { "completeSolution": "...", "multipleStrategies": [], "commonMisconceptions": [], "successCriteria": [] } ],
        "challenge": [ { "completeSolution": "...", "multipleStrategies": [], "commonMisconceptions": [], "successCriteria": [] } ]
      }
    }
  `;

  try {
    const response = await ai.models.generateContentStream({
        model: 'gemini-3-flash-preview',
        contents: prompt,
        config: {
            temperature: 0.8,
        }
    });

    return response;

  } catch (error) {
    console.error("Error calling Gemini API:", error);
    throw new Error("Failed to generate word problems. Please check your API key and try again.");
  }
}

