            <label htmlFor="mathStrand" className="block text-sm font-medium text-slate-700 mb-1">Topic / Strand</label>
            <select id="mathStrand" name="mathStrand" value={formState.mathStrand} onChange={handleInputChange} className="w-full border-slate-300 rounded-md shadow-sm focus:ring-purple-500 focus:border-purple-500">
              {MATH_STRANDS.map(s => <option key={s} value={s}>{s}</option>)}
            </select>
          </div>
          <div>
            <label htmlFor="curriculum" className="block text-sm font-medium text-slate-700 mb-1">Canadian Curriculum</label>
            <select id="curriculum" name="curriculum" value={formState.curriculum} onChange={handleInputChange} className="w-full border-slate-300 rounded-md shadow-sm focus:ring-purple-500 focus:border-purple-500">
              {CURRICULA.map(c => <option key={c} value={c}>{c}</option>)}
            </select>
          </div>
           <div className="md:col-span-2">
            <label htmlFor="numberOfQuestions" className="block text-sm font-medium text-slate-700 mb-1">Number of Questions</label>
            <select id="numberOfQuestions" name="numberOfQuestions" value={formState.numberOfQuestions} onChange={handleInputChange} className="w-full border-slate-300 rounded-md shadow-sm focus:ring-purple-500 focus:border-purple-500">
              {QUESTION_COUNT_OPTIONS.map(n => <option key={n} value={n}>{n} Questions</option>)}
            </select>
          </div>
          <div className="md:col-span-2">
             <label className="block text-sm font-medium text-slate-700 mb-2">Context / Theme</label>
             <div className="flex flex-wrap gap-2">
                {CONTEXTS.map(c => (
                    <button key={c.id} onClick={() => handleContextChange(c.id)}
                        className={`px-4 py-2 rounded-full text-sm font-semibold border-2 transition-colors flex items-center gap-2 ${formState.context === c.id ? 'bg-purple-600 text-white border-purple-600' : 'bg-white text-slate-700 border-slate-300 hover:bg-slate-100'}`}>
                        <span>{formState.context === c.id ? '✓' : c.icon}</span>
                        {c.name}
                    </button>
                ))}
             </div>
          </div>
        </div>
      </FormSection>

      <FormSection title="Select Differentiation Levels">
        <div className="space-y-4">
            <ToggleSwitch 
              label="Scaffolded Support" 
              icon={<ScaffoldIcon />} 
              enabled={formState.differentiation.scaffolded} 
              onToggle={() => handleDifferentiationToggle('scaffolded')}
              description="For students needing extra guidance, using simpler numbers and more direct language."
            />
            <ToggleSwitch 
              label="On-Level" 
              icon={<OnLevelIcon />} 
              enabled={formState.differentiation.onLevel} 
              onToggle={() => handleDifferentiationToggle('onLevel')} 
              description="Meets grade-level expectations and directly reflects curriculum standards."
            />
            <ToggleSwitch 
              label="Challenge Mode" 
              icon={<ChallengeIcon />} 
              enabled={formState.differentiation.challenge} 
              onToggle={() => handleDifferentiationToggle('challenge')}
              description="For students ready for enrichment, often requiring multi-step or abstract thinking."
            />
        </div>
      </FormSection>

      <FormSection title="Additional Supports">
        <div className="grid grid-cols-1 sm:grid-cols-2 gap-x-8 gap-y-4">
            {Object.keys(formState.supports).map((supportKey) => {
                const key = supportKey as keyof FormState['supports'];
                const label = key.replace(/([A-Z])/g, ' $1').replace(/^./, (str) => str.toUpperCase());
                return (
                    <label key={key} className="flex items-center space-x-3 cursor-pointer">
                        <input type="checkbox" checked={formState.supports[key]} onChange={() => handleSupportChange(key)} className="h-5 w-5 rounded border-gray-300 text-purple-600 focus:ring-purple-500" />
                        <span className="text-slate-700">{label}</span>
                    </label>
                );
            })}
        </div>
      </FormSection>
    </div>
  );
};

import React from 'react';

interface ToggleSwitchProps {
  label: string;
  icon: React.ReactNode;
  enabled: boolean;
  onToggle: () => void;
  description: string;
}

export const ToggleSwitch: React.FC<ToggleSwitchProps> = ({ label, icon, enabled, onToggle, description }) => {
  return (
    <div
      onClick={onToggle}
      className={`p-3 border-2 rounded-lg cursor-pointer transition-all flex flex-col ${
        enabled ? 'border-purple-500 bg-purple-50' : 'border-slate-300 bg-white hover:bg-slate-50'
      }`}
    >
      <div className="flex items-start justify-between gap-4 w-full">
        <div className="flex items-center space-x-3">
          <span className={enabled ? 'text-purple-600' : 'text-slate-500'}>{icon}</span>
          <span className={`font-semibold ${enabled ? 'text-purple-800' : 'text-slate-700'}`}>{label}</span>
        </div>
        <div className={`relative flex-shrink-0 w-12 h-6 rounded-full flex items-center transition-colors ${enabled ? 'bg-purple-500' : 'bg-slate-300'}`}>
          <span
            className={`absolute left-0 inline-block w-5 h-5 bg-white rounded-full shadow transform transition-transform ${
              enabled ? 'translate-x-6' : 'translate-x-1'
            }`}
          />
        </div>
      </div>
      <p className="text-xs text-slate-500 mt-2">{description}</p>
    </div>
  );
};

import React, { useState, useCallback } from 'react';
import { AppHeader } from './components/Header';
import { SettingsForm } from './components/SettingsForm';
import { OutputDisplay } from './components/OutputDisplay';
import type { FormState, GeneratedProblem } from './types';
import { generateWordProblemsStream } from './services/geminiService';
import { DEFAULT_FORM_STATE } from './constants';
import { GoogleDocsIcon, StudentSheetIcon } from './components/icons';
import { MatrixStream } from './components/MatrixStream';

export default function App() {
  const [formState, setFormState] = useState<FormState>(DEFAULT_FORM_STATE);
  const [generatedContent, setGeneratedContent] = useState<GeneratedProblem | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [activeView, setActiveView] = useState<'student' | 'teacher'>('student');
  const [streamingText, setStreamingText] = useState<string | null>(null);
  const [activeDifferentiationLevel, setActiveDifferentiationLevel] = useState<'scaffolded' | 'onLevel' | 'challenge' | null>(null);


  const handleGenerate = useCallback(async () => {
    setIsLoading(true);
    setError(null);
    setGeneratedContent(null);
    setStreamingText('');
    setActiveDifferentiationLevel(null);

    try {
      const stream = await generateWordProblemsStream(formState);
      let accumulatedText = '';
      for await (const chunk of stream) {
          const chunkText = chunk.text;
          if (chunkText) {
              accumulatedText += chunkText;
              setStreamingText(accumulatedText); // Still needed to trigger loading UI
          }
      }

      const content = JSON.parse(accumulatedText);
      setGeneratedContent(content);

      const availableLevels = Object.keys(content.studentWorksheet).filter(level => {
        const key = level as keyof typeof content.studentWorksheet;
        return content.studentWorksheet[key] && content.studentWorksheet[key]!.length > 0;
      });
      if (availableLevels.length > 0) {
        setActiveDifferentiationLevel(availableLevels[0] as 'scaffolded' | 'onLevel' | 'challenge');
      }

      setStreamingText(null);

    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred.');
      setStreamingText(null);
      console.error(err);
    } finally {
      setIsLoading(false);
    }
  }, [formState]);

  const handlePrint = () => {
    window.print();
  };


  return (
    <div className="bg-slate-50 min-h-screen font-sans text-slate-800">
      <AppHeader />
      <div className="container mx-auto px-4 py-8 max-w-7xl">
        <main className="mt-8">
          <div className="flex flex-col lg:flex-row lg:space-x-8">
            {/* --- Left Panel (Controls) --- */}
            <div className="w-full lg:w-[35%] lg:flex-shrink-0">
              <div className="lg:sticky lg:top-8 space-y-6">
                <SettingsForm formState={formState} setFormState={setFormState} />
                <div className="text-center">
                  <button
                    onClick={handleGenerate}
                    disabled={isLoading}
                    className="bg-green-600 hover:bg-green-700 disabled:bg-green-400 text-white font-bold py-4 px-12 rounded-lg text-xl shadow-lg transition-transform transform hover:scale-105 disabled:scale-100 disabled:cursor-wait w-full"
                  >
                    {isLoading ? 'Generating...' : 'Generate Word Problems'}
                  </button>
                </div>
              </div>
            </div>

            {/* --- Right Panel (Output) --- */}
            <div className="w-full lg:w-[65%] mt-8 lg:mt-0">
              {isLoading && streamingText !== null && (
                <div className="bg-slate-900 text-white p-4 rounded-lg shadow-md animate-fade-in min-h-[500px] relative overflow-hidden">
                  <MatrixStream />
                  <div className="absolute inset-0 flex items-center justify-center bg-black bg-opacity-50">
                      <h3 className="text-xl font-semibold text-slate-100 flex items-center gap-3 drop-shadow-lg">
                        <div className="w-5 h-5 border-2 border-slate-300 border-t-transparent rounded-full animate-spin"></div>
                        Generating Response...
                      </h3>
                  </div>
                </div>
              )}

              {error && (
                <div className="bg-red-100 border-l-4 border-red-500 text-red-700 p-4 rounded-md" role="alert">
                  <p className="font-bold">Error</p>
                  <p>{error}</p>
                </div>
              )}

              {generatedContent && !isLoading && (
                <div className="bg-white p-6 rounded-lg shadow-md">
                  <div id="printable-area">
                    <OutputDisplay 
                        content={generatedContent} 
                        activeView={activeView}
                        setActiveView={setActiveView}
                        printInfo={{
                          mathConcept: formState.mathConcept,
                          gradeLevel: formState.gradeLevel
                        }}
                        activeDifferentiationLevel={activeDifferentiationLevel}
                        setActiveDifferentiationLevel={setActiveDifferentiationLevel as (level: 'scaffolded' | 'onLevel' | 'challenge') => void}
                    />
                  </div>

                  <div className="mt-8 border-t pt-6 flex flex-col sm:flex-row sm:justify-around space-y-3 sm:space-y-0 sm:space-x-3 no-print">
                    <button onClick={handlePrint} className="flex items-center justify-center space-x-3 text-slate-600 hover:text-purple-600 hover:bg-purple-50 w-full text-left p-3 rounded-md transition-colors font-semibold">
                        <StudentSheetIcon />
                        <span>Print Worksheet / Key</span>
                    </button>
                    <button className="flex items-center justify-center space-x-3 text-slate-400 cursor-not-allowed w-full text-left p-3 rounded-md font-semibold" disabled>
                        <GoogleDocsIcon />
                        <span>Export to Google Docs</span>
                    </button>
                  </div>
                </div>
              )}

              {!isLoading && !generatedContent && !error && (
                  <div className="flex items-center justify-center h-full bg-white p-6 rounded-lg shadow-md min-h-[500px]">
                      <div className="text-center text-slate-500">
                          <svg xmlns="http://www.w3.org/2000/svg" className="mx-auto h-16 w-16 text-slate-400" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="1.5" d="M13 10V3L4 14h7v7l9-11h-7z" /></svg>
                          <h3 className="mt-2 text-xl font-semibold text-slate-800">Generated problems will appear here</h3>
                          <p className="mt-1 text-slate-500">Adjust the settings on the left and click "Generate" to begin.</p>
                      </div>
                  </div>
              )}
            </div>
          </div>
        </main>
      </div>
    </div>
  );
}

import React from 'react';
import type { GeneratedProblem } from '../types';

type DifferentiationLevel = 'scaffolded' | 'onLevel' | 'challenge';

interface OutputDisplayProps {
  content: GeneratedProblem;
  activeView: 'student' | 'teacher';
  setActiveView: (view: 'student' | 'teacher') => void;
  printInfo: {
    mathConcept: string;
    gradeLevel: string;
  };
  activeDifferentiationLevel: DifferentiationLevel | null;
  setActiveDifferentiationLevel: (level: DifferentiationLevel) => void;
}

const LEVEL_NAMES: Record<DifferentiationLevel, string> = {
  scaffolded: 'Scaffolded',
  onLevel: 'On-Level',
  challenge: 'Challenge'
};

export const OutputDisplay: React.FC<OutputDisplayProps> = ({ 
  content, 
  activeView, 
  setActiveView, 
  printInfo,
  activeDifferentiationLevel,
  setActiveDifferentiationLevel
}) => {

  const availableLevels = (Object.keys(content.studentWorksheet) as DifferentiationLevel[])
    .filter(level => content.studentWorksheet[level] && content.studentWorksheet[level]!.length > 0);

  const renderProblemList = (level: DifferentiationLevel, title: string) => {
    const problems = content.studentWorksheet[level];
    if (!problems || problems.length === 0) return null;

    return (
      <div key={level} className="mt-8 first:mt-0 break-inside-avoid">
        {availableLevels.length <= 1 && <h3 className="text-2xl font-bold text-purple-700 mb-4 pb-2 border-b">{title}</h3>}
        <div className="space-y-10">
          {problems.map((problem, index) => (
            <div key={`${level}-${index}`} className="break-inside-avoid">
              <p className="font-semibold text-slate-800 mb-2">Problem {index + 1}</p>
              <p className="mb-4 whitespace-pre-wrap">{problem.problemText}</p>

              {problem.stepByStepHints && problem.stepByStepHints.length > 0 && (
                <div className="mb-4 p-4 border border-purple-200 bg-purple-50/50 rounded-md">
                  <h6 className="font-semibold text-sm text-purple-800 mb-2">💡 Step-by-Step Hints</h6>
                  <ol className="list-decimal list-inside text-slate-700 space-y-1">
                    {problem.stepByStepHints.map((hint, hintIndex) => (
                      <li key={hintIndex}>{hint}</li>
                    ))}
                  </ol>
                </div>
              )}

              <div className="border-t border-dashed pt-4">
                <p className="italic text-slate-600">{problem.workspacePrompt}</p>
                <div className="mt-4 min-h-[8rem] border rounded-md bg-slate-50 p-2"></div>
              </div>
            </div>
          ))}
        </div>
      </div>
    );
  };

  const renderTeacherKeyList = (level: DifferentiationLevel, title: string) => {
    const keys = content.teacherKey[level];
    if (!keys || keys.length === 0) return null;

    return (
      <div key={level} className="mt-8 first:mt-0 break-inside-avoid">
        {availableLevels.length <= 1 && <h3 className="text-2xl font-bold text-purple-700 mb-4 pb-2 border-b">{title}</h3>}
        <div className="space-y-8">
          {keys.map((key, index) => (
            <div key={`${level}-key-${index}`} className="p-4 border border-slate-200 rounded-lg bg-slate-50/50 break-inside-avoid">
              <h4 className="text-xl font-bold text-slate-800 mb-3">Problem {index + 1} Key</h4>
              <div className="space-y-4">
                <div>
                  <h5 className="font-semibold text-slate-800">Complete Solution:</h5>
                  <p className="text-slate-700 whitespace-pre-wrap">{key.completeSolution}</p>
                </div>
                <div>
                  <h5 className="font-semibold text-slate-800">Multiple Strategies:</h5>
                  <ul className="list-disc list-inside text-slate-700 space-y-1">
                    {key.multipleStrategies.map((s, i) => <li key={i}>{s}</li>)}
                  </ul>
                </div>
                <div>
                  <h5 className="font-semibold text-slate-800">Common Misconceptions:</h5>
                  <ul className="list-disc list-inside text-slate-700 space-y-1">
                    {key.commonMisconceptions.map((m, i) => <li key={i}>{m}</li>)}
                  </ul>
                </div>
                <div>
                  <h5 className="font-semibold text-slate-800">Success Criteria:</h5>
                  <ul className="list-disc list-inside text-slate-700 space-y-1">
                    {key.successCriteria.map((c, i) => <li key={i}>{c}</li>)}
                  </ul>
                </div>
              </div>
            </div>
          ))}
        </div>
      </div>
    );
  };

  return (
    <div className="prose max-w-none">
      <div className="flex justify-center mb-6 no-print">
        <div className="bg-slate-100 p-1 rounded-lg flex space-x-1">
          <button onClick={() => setActiveView('student')} className={`px-4 py-2 rounded-md font-semibold transition-colors ${activeView === 'student' ? 'bg-white text-purple-600 shadow' : 'text-slate-600 hover:bg-slate-200'}`}>Student Worksheet</button>
          <button onClick={() => setActiveView('teacher')} className={`px-4 py-2 rounded-md font-semibold transition-colors ${activeView === 'teacher' ? 'bg-white text-purple-600 shadow' : 'text-slate-600 hover:bg-slate-200'}`}>Teacher Key</button>
        </div>
      </div>

      {availableLevels.length > 1 && (
        <div className="flex justify-center mb-6 border-b no-print">
          <div className="flex space-x-1">
            {availableLevels.map(level => (
              <button
                key={level}
                onClick={() => setActiveDifferentiationLevel(level)}
                className={`px-4 py-2 font-semibold text-sm rounded-t-md transition-colors border-b-2 ${
                  activeDifferentiationLevel === level
                    ? 'border-purple-600 text-purple-700'
                    : 'border-transparent text-slate-500 hover:text-purple-600 hover:border-slate-300'
                }`}
              >
                {LEVEL_NAMES[level]}
              </button>
            ))}
          </div>
        </div>
      )}

      <div className="print-only hidden print:block mb-8">
          <h1 className="text-3xl font-bold mb-2">Math Word Problems: {printInfo.mathConcept}</h1>
          <h2 className="text-xl text-gray-600">Grade {printInfo.gradeLevel} &ndash; {activeDifferentiationLevel ? LEVEL_NAMES[activeDifferentiationLevel] : ''} &ndash; {activeView === 'teacher' ? 'Teacher Answer Key' : 'Student Worksheet'}</h2>
      </div>

      {activeDifferentiationLevel && (
        <>
          {activeView === 'student' && (
            <div id="student-worksheet">
              {renderProblemList(activeDifferentiationLevel, `${LEVEL_NAMES[activeDifferentiationLevel]} Problems`)}
            </div>
          )}

          {activeView === 'teacher' && (
            <div id="teacher-key">
              {renderTeacherKeyList(activeDifferentiationLevel, `${LEVEL_NAMES[activeDifferentiationLevel]} Problem Keys`)}
            </div>
          )}
        </>
      )}
    </div>
  );
};

import { GoogleGenAI, Type } from "@google/genai";
import type { FormState, GeneratedProblem } from '../types';

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

// FIX: Define a schema for the expected JSON response to ensure type safety and valid output.
const problemDetailSchema = {
    type: Type.OBJECT,
    properties: {
        problemText: { type: Type.STRING, description: "The core, student-friendly word problem." },
        stepByStepHints: {
            type: Type.ARRAY,
            items: { type: Type.STRING },
            description: "An array of strings, with each string being a distinct step to guide the student. Omit or leave empty if not requested."
        },
        workspacePrompt: { type: Type.STRING, description: "A generic prompt for students to show their mathematical thinking." },
    },
    required: ['problemText', 'workspacePrompt']
};

const teacherKeyDetailSchema = {
    type: Type.OBJECT,
    properties: {
        completeSolution: { type: Type.STRING, description: "A complete solution to the problem." },
        multipleStrategies: { type: Type.ARRAY, items: { type: Type.STRING }, description: "Suggestions for multiple strategies to solve the problem." },
        commonMisconceptions: { type: Type.ARRAY, items: { type: Type.STRING }, description: "A list of common misconceptions students might have." },
        successCriteria: { type: Type.ARRAY, items: { type: Type.STRING }, description: "A list of success criteria for assessment." },
    },
    required: ['completeSolution', 'multipleStrategies', 'commonMisconceptions', 'successCriteria']
};

const responseSchema = {
    type: Type.OBJECT,
    properties: {
        studentWorksheet: {
            type: Type.OBJECT,
            properties: {
                scaffolded: { type: Type.ARRAY, items: problemDetailSchema },
                onLevel: { type: Type.ARRAY, items: problemDetailSchema },
                challenge: { type: Type.ARRAY, items: problemDetailSchema },
            },
        },
        teacherKey: {
            type: Type.OBJECT,
            properties: {
                scaffolded: { type: Type.ARRAY, items: teacherKeyDetailSchema },
                onLevel: { type: Type.ARRAY, items: teacherKeyDetailSchema },
                challenge: { type: Type.ARRAY, items: teacherKeyDetailSchema },
            },
        }
    },
    required: ['studentWorksheet', 'teacherKey']
};


export async function generateWordProblemsStream(settings: FormState) {
  const selectedLevels = Object.entries(settings.differentiation)
    .filter(([, value]) => value)
    .map(([key]) => key);

  if (selectedLevels.length === 0) {
    throw new Error("Please select at least one differentiation level.");
  }

  const selectedSupports = Object.entries(settings.supports)
    .filter(([, value]) => value)
    .map(([key]) => key.replace(/([A-Z])/g, ' $1').toLowerCase());

  // FIX: Simplified prompt as the JSON structure is now enforced by the API via responseSchema.
  const prompt = `
    You are an expert curriculum designer and math teacher specializing in creating differentiated, inclusive, and curriculum-aligned math word problems for K-12 students in Canada. Your response will be a JSON object containing a student worksheet and a teacher key.

    Generate a set of ${settings.numberOfQuestions} unique math word problems for EACH of the differentiation levels specified below.

    Your generation task is defined by these criteria:
    - Math Concept: ${settings.mathConcept}
    - Grade Level: ${settings.gradeLevel}
    - Curriculum: ${settings.curriculum}
    - Context/Theme: ${settings.context}
    - Differentiation Levels to generate for: ${selectedLevels.join(', ')}. Create a complete and distinct worksheet for each of these levels.
    - Additional Supports to include: ${selectedSupports.join(', ') || 'None'}

    For each problem in each worksheet, provide:
    - For the 'studentWorksheet': a student-friendly word problem, step-by-step hints (if requested), and a prompt for a workspace.
    - For the 'teacherKey': a complete solution, multiple strategies, common misconceptions, and success criteria.

    Ensure the language is inclusive, classroom-appropriate, and aligned with Universal Design for Learning (UDL) principles.
  `;

  try {
    // FIX: Added responseMimeType and responseSchema to ensure valid JSON output.
    const response = await ai.models.generateContentStream({
        model: 'gemini-3-flash-preview',
        contents: prompt,
        config: {
            temperature: 0.8,
            responseMimeType: "application/json",
            responseSchema: responseSchema,
        }
    });

    return response;

  } catch (error) {
    console.error("Error calling Gemini API:", error);
    throw new Error("Failed to generate word problems. Please check your API key and try again.");
  }
}

